using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class RankedTimeRecodingDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Unit-factor recodings retain the original parallel-edge rank.",
        H("Unit-factor recodings retain the original parallel-edge rank"),
        Blocks(
            Paragraph(Text("edgeCast transports literal numbered edges through a matrix equality and preserves source, target and number. rank_identity reuses Finset.orderEmbOfFin_unique and is consumed by both unit-factor ranking proofs. join_right_identity and join_left_identity prove that collapsing the unique identity half-edge leaves the original A-edge number unchanged; they use the existing fiber_number_lt_iff, including empty fibers.")),
            Paragraph(Text("The retained join_left_identity and join_right_identity identify the actual ranked half-edges used by recoding_time. After the two matrix-equality transports, the (A,1) elementary recoding is forward unit time. For every finite dimension n and every nonzero d, relative_time gives the actual primitive d-orbit cardinality in ZMod d. No invertibility, nonempty orbit stratum or three-divisibility hypothesis is added.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-rankedtimerecoding-join-right-identity"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.join_right_identity"), H("join_right_identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Lex ranking really retains the original A-edge number in A*I. Only the identity half-edge is collapsed, including empty fibres."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-rankedtimerecoding-join-left-identity"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.join_left_identity"), H("join_left_identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The same rank argument for I*A uses the other coordinate of the pair. This is not inferred from the A*I case or from beam-action equality."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-rankedtimerecoding-recoding-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.recoding_time"), H("recoding_time"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Actual forward convention: the S-half at t joins the R-half at t+1."))), DescribeRole.Theorem),
            
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-edge-cast"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.edgeCast"), H("edgeCast"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Literal transport of numbered edges through an equality of matrices.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-edge-cast-symm-apply"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.edgeCast_symm_apply"), H("edgeCast_symm_apply"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Transporting a numbered edge along a matrix equality and back recovers the same edge. This cancels the equality casts around a recoding.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-edge-cast-source"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.edgeCast_source"), H("edgeCast_source"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Transport along a matrix equality preserves the source vertex. This keeps castTimed compatible with path incidence.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-edge-cast-target"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.edgeCast_target"), H("edgeCast_target"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Transport along a matrix equality preserves the target vertex. No vertex reindexing is hidden in the cast.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-edge-cast-number"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.edgeCast_number"), H("edgeCast_number"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The underlying edge number is unchanged by matrix-equality transport. This keeps the original ranking in the identity-factor calculations.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-cast-timed"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.castTimed"), H("castTimed"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Transport every path coordinate along the literal matrix equality. The resulting path equivalence commutes with signed time.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-cast-coordinate"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.cast_coordinate"), H("cast_coordinate"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("At each integer coordinate, castTimed is exactly the numbered edge cast. This identifies its action before computing phases.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-cast-gyration"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.cast_gyration"), H("cast_gyration"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Matrix-equality transport contributes zero gyration on every nonzero primitive stratum. This removes the two literal casts in the time and identity recodings.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-identity-edge"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.identityEdge"), H("identityEdge"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("There is exactly one identity edge at this vertex; its actual number is 0.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-rank-identity"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.rank_identity"), H("rank_identity"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Consumed rank helper. This is direct reuse of the public finite ordered embedding uniqueness theorem, not a second proof of that library result.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-split-right-identity"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.split_right_identity"), H("split_right_identity"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Splitting an edge in A times the identity recovers that A edge and the unique identity edge at its target. The original A-edge number is retained.")))),
            
            Describe.Remark(DescribeId.Create("positive-recoding-rankedtimerecoding-relative-time"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/RankedTimeRecoding.relative_time"), H("relative_time"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The genuine original-ranked primitive-orbit sum, at ALL nonzero periods.")))))));
}
